def pub(u):
    h = re.sub(r'^https?://(www\.)?', '', u).split('/')[0]
    m = re.match(r'https?://(?:dx\.)?doi\.org/(10\.\d+)', u)   # a DOI link names no publisher: the DOI prefix does (14 Nov 2026: « Doi » on a sources page)
    if m: return DOI.get(m.group(1), 'Journal article')
    if re.search(r'/CIK-\d+/', u): return 'SEC filing'          # SEC documents served from a CDN (Neocloud: cloudfront.net/CIK-0001769628)
    if h in PUB: return PUB[h]
    m = re.match(r'([a-z0-9-]+)\.(gcs-web|q4web|q4ir|irpass)\.com$', h)   # investor-relations hosts: the sub-domain is the company (iren.gcs-web.com, 19 Nov 2026)
    if m: return m.group(1).upper() if len(m.group(1)) <= 4 else m.group(1).title()
    for k, v in PUB.items():
        if h.endswith('.' + k): return v
    b = site_label(u)
    g = b.replace('-', ' ').title().replace('Biopharma', 'Biopharma')
    # a name guessed from the domain (« Chaidiscovery », « Isomorphiclabs ») reached 30 lines of the AI drug discovery sources
    # (20 Nov 2026): print it, so PUB gets the real name before the review
    if len(g) > 9 and ' ' not in g: print('PUBLISHER GUESSED', h, '->', g, ': add the real name to PUB')
    return g
